import { Component, computed, input, output } from '@angular/core';

@Component({
  selector: 'app-seat-tile',
  imports: [],
  templateUrl: './seat-tile.html',
  styleUrl: './seat-tile.scss',
})
export class SeatTile {
  readonly reihe = input.required<string>();
  readonly spalte = input.required<number>();
  readonly status = input.required<'Frei' | 'Belegt'>();
  readonly ausgewaehlt = input<boolean>(false);
  readonly fokussierbar = input<boolean>(false);

  readonly auswahlUmschalten = output<void>();

  protected readonly code = computed(() => `${this.reihe()}${this.spalte()}`);
  protected readonly ariaLabel = computed(() => {
    if (this.status() === 'Belegt') {
      return `Reihe ${this.reihe()}, Platz ${this.spalte()}, belegt`;
    }
    return `Reihe ${this.reihe()}, Platz ${this.spalte()}, ${this.ausgewaehlt() ? 'ausgewählt' : 'frei'}`;
  });

  protected onKlick(): void {
    if (this.status() === 'Belegt') return;
    this.auswahlUmschalten.emit();
  }
}
---html---
<div
  class="seat-tile"
  [class.seat-tile--belegt]="status() === 'Belegt'"
  [class.seat-tile--ausgewaehlt]="ausgewaehlt() && status() !== 'Belegt'"
  [attr.aria-label]="ariaLabel()"
  [attr.data-code]="code()"
  [attr.tabindex]="fokussierbar() ? 0 : -1"
  [attr.role]="status() === 'Belegt' ? null : 'button'"
  [attr.aria-pressed]="status() === 'Belegt' ? null : ausgewaehlt()"
  [title]="code()"
  (click)="onKlick()"
>
  @if (status() === 'Belegt') {
    <span class="seat-tile__icon" aria-hidden="true">✕</span>
  } @else if (ausgewaehlt()) {
    <span class="seat-tile__icon" aria-hidden="true">✓</span>
  } @else {
    <span class="seat-tile__code" aria-hidden="true">{{ code() }}</span>
  }
</div>
---buchung.html---
@if (ladezustand() === 'laedt') {
  <div class="sitzplan" aria-busy="true" aria-label="Sitzplan wird geladen">
    @for (reihe of skeletonReihen; track reihe) {
      <div class="sitzplan__reihe">
        <div class="sitzplan__reihen-label"></div>
        @for (spalte of skeletonSpalten; track spalte) {
          <div class="sitzplan__skeleton-kachel"></div>
        }
      </div>
    }
  </div>
} @else if (ladezustand() === 'fehler') {
  <p class="buchung__fehler" role="alert">
    Sitzplan konnte nicht geladen werden. Bitte versuchen Sie es später erneut.
  </p>
} @else if (sitzplan(); as plan) {
  <div class="sitzplan" #sitzplanContainer (keydown)="onSitzplanKeydown($event)">
    @for (reihe of plan.reihen; track reihe.reihe) {
      <div class="sitzplan__reihe">
        <div class="sitzplan__reihen-label">{{ reihe.reihe }}</div>
        @for (position of reihe.positionen; track position.spalte) {
          @if (position.typ === 'Gang') {
            <div class="sitzplan__luecke" aria-hidden="true"></div>
          } @else {
            <app-seat-tile
              [reihe]="reihe.reihe"
              [spalte]="position.spalte"
              [status]="position.status!"
              [ausgewaehlt]="ausgewaehlteCodes().has(position.code!)"
              [fokussierbar]="istFokussiert(reihe.reihe, position.spalte)"
              (auswahlUmschalten)="aufKachelKlick(reihe.reihe, position.spalte, position.code!)"
            />
          }
        }
      </div>
    }
  </div>
}

