        var ergebnis = await service.GetVeranstaltungenAsync(von: new DateOnly(2026, 9, 15));

        Assert.Equal(["E-in-bereich", "E-auf-bis", "E-nach-bereich"], ergebnis.Select(v => v.Id));
    }

    [Fact]
