        var ergebnis = await service.GetVeranstaltungenAsync(bis: new DateOnly(2026, 9, 15));

        Assert.Equal(["E-vor-bereich", "E-auf-von", "E-in-bereich"], ergebnis.Select(v => v.Id));
    }

    [Fact]
